import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import 'app_log.dart';
// Generated by `flutterfire configure` (see README.md).
import 'firebase_options.dart';
import 'screens/home_screen.dart';
import 'screens/login_screen.dart';
import 'screens/splash_screen.dart';
import 'services/auth.dart' as auth;
import 'theme.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]);
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const GatorGraspApp());
}

class GatorGraspApp extends StatelessWidget {
  const GatorGraspApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'GatorGrasp',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        brightness: Brightness.dark,
        scaffoldBackgroundColor: GG.background,
        colorScheme: ColorScheme.fromSeed(
          seedColor: GG.orange,
          brightness: Brightness.dark,
        ),
      ),
      home: const AuthGate(),
    );
  }
}

/// Shows the login screen or the home screen depending on Firebase auth state.
class AuthGate extends StatefulWidget {
  const AuthGate({super.key});

  @override
  State<AuthGate> createState() => _AuthGateState();
}

class _AuthGateState extends State<AuthGate> {
  /// How long the splash stays up at minimum, even if auth resolves sooner.
  static const _splashMin = Duration(milliseconds: 1800);

  final _log = AppLog();
  late final Stream<User?> _user = auth.onUser();
  bool _splashDone = false;

  @override
  void initState() {
    super.initState();
    Future.delayed(_splashMin, () {
      if (mounted) setState(() => _splashDone = true);
    });
  }

  @override
  void dispose() {
    _log.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: SystemUiOverlayStyle.light,
      child: Scaffold(
        backgroundColor: GG.background,
        body: SafeArea(
          child: StreamBuilder<User?>(
            stream: _user,
            builder: (context, snap) {
              final user = snap.data;
              // Splash until both the minimum time has passed and Firebase
              // knows whether someone is signed in, then fade to the next screen.
              final Widget child;
              if (!_splashDone ||
                  snap.connectionState == ConnectionState.waiting) {
                child = const SplashScreen(key: ValueKey('splash'));
              } else if (user == null) {
                child = const LoginScreen(key: ValueKey('login'));
              } else {
                child =
                    HomeScreen(key: ValueKey(user.uid), user: user, log: _log);
              }
              return AnimatedSwitcher(
                duration: const Duration(milliseconds: 400),
                child: child,
              );
            },
          ),
        ),
      ),
    );
  }
}
